package com.finguard.security;
import com.finguard.service.UserService;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserService users; public JwtAuthenticationFilter(JwtService jwt,UserService users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.claims(h.substring(7)); var u=users.byEmail(c.getSubject()); var a=new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))); SecurityContextHolder.getContext().setAuthentication(a);}catch(RuntimeException ignored){} chain.doFilter(req,res);}}
